from pathlib import Path
from datetime import datetime
import base64
import shutil
import py_compile

ROOT = Path.cwd()

REQUIRED = [
    ROOT / "src/scoring/research_scoring.py",
    ROOT / "config/treatment_keywords.yml",
]

missing = [str(p) for p in REQUIRED if not p.exists()]
if missing:
    print("エラー：clinic-list-filter-complete フォルダで実行してください。")
    print("見つからないファイル:")
    for p in missing:
        print(" -", p)
    raise SystemExit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup = ROOT / f"code_backup_research_v24_{stamp}"
backup.mkdir(parents=True, exist_ok=False)

targets = [
    ROOT / "src/scoring/research_scoring.py",
    ROOT / "config/treatment_keywords.yml",
    ROOT / "export_research_v24_results.py",
]
for p in targets:
    if p.exists():
        rel = p.relative_to(ROOT)
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, dst)

PAYLOADS = {
    'src/scoring/research_scoring.py': '',
    'config/treatment_keywords.yml': '',
    'export_research_v24_results.py': '',
}

try:
    for rel, encoded in PAYLOADS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))

    py_compile.compile(str(ROOT / "src/scoring/research_scoring.py"), doraise=True)
    py_compile.compile(str(ROOT / "export_research_v24_results.py"), doraise=True)
    (ROOT / "VERSION_RESEARCH").write_text("2.4-research\n", encoding="utf-8")

except Exception as e:
    print("適用中にエラーが発生したため、バックアップから戻します。")
    for p in targets:
        rel = p.relative_to(ROOT)
        src = backup / rel
        if src.exists():
            p.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, p)
    print("エラー:", repr(e))
    raise SystemExit(1)

print("修正しました。")
print("・v24：ED / 男性更年期を独立した治療カテゴリとして扱います。")
print("・ED / 男性更年期だけで泌尿器科にはしません。")
print("・泌尿器科と明記されたメニュー、前立腺・尿路結石・膀胱鏡などは引き続き泌尿器科カテゴリです。")
print("・サイトマップ、院長紹介、当院について、アクセス、料金、問い合わせ等は独立治療ページの根拠にしません。")
print("・サイト名に clinic が含まれるだけで全ページを医院紹介ページ扱いしないようにしました。")
print("・医院紹介/診療案内ページ内の実際の治療タブ・メニューは引き続きカテゴリ根拠にします。")
print("・年齢推定、広告・集客施策、昼の検査・手術枠ロジックは v23 の内容を維持します。")
print("・SQLite、UUID、Google Maps取込結果、Comdesk元データは変更していません。")
print("・比較用出力: export_research_v24_results.py")
print("バックアップ:", backup.name)
